content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-border: #bfdbfe;

  --metric-tag-bg: #ecfdf5;
  --metric-tag-text: #047857;
  --metric-tag-border: #a7f3d0;

  --imperial-tag-bg: #fffbeb;
  --imperial-tag-text: #b45309;
  --imperial-tag-border: #fde68a;

  --bg-gradient-start: #f8fafc;
  --bg-gradient-end: #e2e8f0;
  --surface-color: #ffffff;
  --surface-muted: #f1f5f9;

  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-tertiary: #94a3b8;

  --border-light: #e2e8f0;
  --border-focus: #3b82f6;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --shadow-active: 0 0 0 3px rgba(37, 99, 235, 0.2);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Hiragino Kaku Gothic ProN", "BIZ UDPGothic", Meiryo, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background: linear-gradient(135deg, var(--bg-gradient-start), var(--bg-gradient-end));
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  padding: 16px 12px;
}

@media (min-width: 640px) {
  body {
    padding: 32px 24px;
  }
}

/* アプリケーション全体コンテナ */
.app-container {
  max-width: 900px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヘッダーエリア */
.header {
  text-align: center;
  padding: 8px 0 4px;
}

.title {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

@media (min-width: 640px) {
  .title {
    font-size: 2.1rem;
  }
}

.subtitle {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-top: 6px;
  word-break: break-word;
}

/* メインレイアウト */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* 入力パネル */
.input-panel {
  background: var(--surface-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-light);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 640px) {
  .input-panel {
    padding: 24px;
  }
}

/* 入力コントロールグループ */
.input-group {
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
  flex-wrap: wrap;
}

@media (min-width: 500px) {
  .input-group {
    flex-wrap: nowrap;
  }
}

.value-input {
  flex: 1 1 180px;
  min-width: 0;
  height: 52px;
  padding: 0 44px 0 16px;
  font-size: 1.4rem;
  font-weight: 600;
  font-family: var(--font-mono);
  color: var(--text-main);
  background-color: var(--surface-color);
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.value-input:focus {
  border-color: var(--primary-color);
  box-shadow: var(--shadow-active);
}

.value-input::placeholder {
  color: var(--text-tertiary);
  font-weight: 400;
}

/* クリアボタン（入力枠内の×ボタン） */
.clear-button {
  position: absolute;
  right: 142px;
  top: 50%;
  transform: translateY(-50%);
  background: var(--surface-muted);
  border: none;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 14px;
  padding: 0;
  transition: all 0.15s ease;
}

@media (max-width: 499px) {
  .clear-button {
    right: 12px;
    top: 26px;
  }
}

.clear-button:hover {
  background: #cbd5e1;
  color: var(--text-main);
}

/* 単位セレクト */
.unit-select {
  flex: 0 0 auto;
  width: 128px;
  height: 52px;
  padding: 0 12px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--surface-muted);
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

@media (max-width: 499px) {
  .unit-select {
    width: 100%;
  }
}

.unit-select:focus {
  border-color: var(--primary-color);
  box-shadow: var(--shadow-active);
}

/* プリセット選択チップ一覧 */
.preset-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.chip-button {
  background-color: var(--surface-muted);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-full);
  padding: 8px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: all 0.15s ease;
  user-select: none;
}

.chip-button:hover {
  background-color: var(--primary-light);
  border-color: var(--primary-border);
  color: var(--primary-color);
  transform: translateY(-1px);
}

.chip-button:active {
  transform: translateY(0);
}

/* 換算結果セクション */
.results-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.results-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

@media (min-width: 600px) {
  .results-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
  }
}

@media (min-width: 860px) {
  .results-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
  }
}

/* 結果表示カード */
.card {
  background: var(--surface-color);
  border-radius: var(--radius-lg);
  border: 1.5px solid var(--border-light);
  box-shadow: var(--shadow-sm);
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  transition: all 0.2s ease;
  position: relative;
}

.card:hover {
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
}

/* 基準単位カードのハイライト */
.card.card-base {
  background-color: #fbfdff;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 1px var(--primary-color), var(--shadow-md);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.unit-label {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.unit-symbol {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
}

.unit-system-tag {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid transparent;
}

.unit-system-tag.metric {
  background-color: var(--metric-tag-bg);
  color: var(--metric-tag-text);
  border-color: var(--metric-tag-border);
}

.unit-system-tag.imperial {
  background-color: var(--imperial-tag-bg);
  color: var(--imperial-tag-text);
  border-color: var(--imperial-tag-border);
}

.card-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.converted-value {
  font-size: 1.5rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--text-main);
  word-break: break-all;
  line-height: 1.25;
}

/* カードフッター・操作ボタン */
.copy-button,
.base-select-button {
  min-height: 38px;
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.15s ease;
  user-select: none;
}

.copy-button {
  background-color: var(--surface-color);
  color: var(--text-secondary);
}

.copy-button:hover {
  background-color: var(--surface-muted);
  color: var(--text-main);
  border-color: #cbd5e1;
}

.base-select-button {
  background-color: transparent;
  color: var(--primary-color);
  border: 1px dashed var(--primary-border);
}

.base-select-button:hover {
  background-color: var(--primary-light);
  border-style: solid;
  border-color: var(--primary-color);
}

.card.card-base .base-select-button {
  background-color: var(--primary-light);
  border: 1px solid var(--primary-border);
  color: var(--primary-color);
  font-weight: 700;
  cursor: default;
}

/* 計算式・解説セクション */
.formula-section {
  background: var(--surface-color);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  margin-top: 8px;
}

.formula-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.formula-box {
  background: var(--surface-muted);
  border-radius: var(--radius-md);
  padding: 14px 16px;
  border-left: 4px solid var(--primary-color);
}

.formula-content {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

.formula-content code {
  font-family: var(--font-mono);
  background-color: rgba(255, 255, 255, 0.8);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  color: var(--primary-hover);
  border: 1px solid var(--border-light);
}

/* クリップボードコピー完了トースト */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(0);
  background: #1e293b;
  color: #ffffff;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 8px;
  z-index: 1000;
  pointer-events: none;
  animation: toastFadeInOut 2.4s ease forwards;
}

@keyframes toastFadeInOut {
  0% {
    opacity: 0;
    transform: translateX(-50%) translateY(16px);
  }
  15% {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
  85% {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
  100% {
    opacity: 0;
    transform: translateX(-50%) translateY(-10px);
  }
}

/* コピーバッジ（カード内インライン通知用） */
.copy-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.75rem;
  color: #16a34a;
  font-weight: 600;
}

export type UnitKey = 'mm' | 'cm' | 'm' | 'km' | 'in' | 'ft';

export interface UnitDefinition {
  key: UnitKey;
  name: string;
  symbol: string;
  system: 'metric' | 'imperial';
  toMeterFactor: number;
  description: string;
}

export interface ConversionResult {
  unit: UnitDefinition;
  value: number;
  formatted: string;
}

export interface CardProps {
  result: ConversionResult;
  isBase: boolean;
  onSelectAsBase: (key: UnitKey) => void;
  onCopy: (text: string, label: string) => void;
}

import { UnitKey, UnitDefinition, ConversionResult } from '../types';

export const UNITS: Record<UnitKey, UnitDefinition> = {
  mm: {
    key: 'mm',
    name: 'ミリメートル',
    symbol: 'mm',
    system: 'metric',
    toMeterFactor: 0.001,
    description: '1 mm = 0.001 m（1メートルの1000分の1）'
  },
  cm: {
    key: 'cm',
    name: 'センチメートル',
    symbol: 'cm',
    system: 'metric',
    toMeterFactor: 0.01,
    description: '1 cm = 0.01 m（1メートルの100分の1）'
  },
  m: {
    key: 'm',
    name: 'メートル',
    symbol: 'm',
    system: 'metric',
    toMeterFactor: 1,
    description: '国際単位系（SI）における長さの基本単位'
  },
  km: {
    key: 'km',
    name: 'キロメートル',
    symbol: 'km',
    system: 'metric',
    toMeterFactor: 1000,
    description: '1 km = 1,000 m（1メートルの1000倍）'
  },
  in: {
    key: 'in',
    name: 'インチ',
    symbol: 'in',
    system: 'imperial',
    toMeterFactor: 0.0254,
    description: '1 in = 正確に 25.4 mm（0.0254 m）'
  },
  ft: {
    key: 'ft',
    name: 'フィート',
    symbol: 'ft',
    system: 'imperial',
    toMeterFactor: 0.3048,
    description: '1 ft = 12 in = 正確に 0.3048 m'
  }
};

export const UNIT_KEYS: UnitKey[] = ['mm', 'cm', 'm', 'km', 'in', 'ft'];

export interface PresetItem {
  label: string;
  value: number;
  unit: UnitKey;
}

export const PRESETS: PresetItem[] = [
  { label: '1 m', value: 1, unit: 'm' },
  { label: '身長 170 cm', value: 170, unit: 'cm' },
  { label: '1 インチ', value: 1, unit: 'in' },
  { label: '1 フィート', value: 1, unit: 'ft' },
  { label: '10 cm', value: 10, unit: 'cm' },
  { label: '1 km', value: 1, unit: 'km' }
];

export function formatNumber(num: number): string {
  if (num === 0) return '0';
  if (isNaN(num) || !isFinite(num)) return '-';

  const absNum = Math.abs(num);

  if (absNum < 0.000001 || absNum >= 100000000) {
    return num.toExponential(4).replace(/\.?0+e/, 'e');
  }

  let formatted = num.toFixed(6);
  if (formatted.indexOf('.') !== -1) {
    formatted = formatted.replace(/\.?0+$/, '');
  }

  const parts = formatted.split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return parts.join('.');
}

export function convertValue(inputValue: number, fromUnitKey: UnitKey): ConversionResult[] {
  const fromUnit = UNITS[fromUnitKey];
  const valueInMeters = inputValue * fromUnit.toMeterFactor;

  return UNIT_KEYS.map((key) => {
    const targetUnit = UNITS[key];
    const convertedValue = valueInMeters / targetUnit.toMeterFactor;

    return {
      unit: targetUnit,
      value: convertedValue,
      formatted: formatNumber(convertedValue)
    };
  });
}

export function getFormulaExplanation(baseUnitKey: UnitKey, inputValue: number): string {
  const baseUnit = UNITS[baseUnitKey];
  const formattedInput = formatNumber(inputValue);
  const meters = inputValue * baseUnit.toMeterFactor;
  const formattedMeters = formatNumber(meters);

  if (baseUnitKey === 'm') {
    return `基準値 ${formattedInput} m はメートル法基準単位です。各単位の定義倍率（km: ÷1000、cm: ×100、mm: ×1000、in: ÷0.0254、ft: ÷0.3048）を適用して同時算出しています。`;
  }

  return `基準値 ${formattedInput} ${baseUnit.symbol} をまず基本単位メートルに換算（${formattedInput} × ${baseUnit.toMeterFactor} = ${formattedMeters} m）し、そこから他全単位へ正確に展開しています。`;
}

import { useState } from 'react';
import { Copy, Check, ArrowRightLeft } from 'lucide-react';
import { CardProps } from '../types';

export default function ConversionCard({
  result,
  isBase,
  onSelectAsBase,
  onCopy
}: CardProps) {
  const [copied, setCopied] = useState<boolean>(false);
  const { unit, formatted } = result;

  const handleCopy = () => {
    const textToCopy = `${formatted} ${unit.symbol}`;
    onCopy?.(textToCopy, `${unit.name} (${unit.symbol})`);
    setCopied(true);
    setTimeout(() => {
      setCopied(false);
    }, 1800);
  };

  const handleSelectAsBase = () => {
    if (!isBase) {
      onSelectAsBase?.(unit.key);
    }
  };

  const systemLabel = unit.system === 'metric' ? 'メートル法' : 'ヤードポンド法';

  return (
    <div className={`card ${isBase ? 'card-base' : ''}`}>
      <div className="card-header">
        <div className="unit-label">
          <span>{unit.name}</span>
          <span className="unit-symbol">{unit.symbol}</span>
        </div>
        <span className={`unit-system-tag ${unit.system}`}>
          {systemLabel}
        </span>
      </div>

      <div className="card-body">
        <div className="converted-value" title={`${formatted} ${unit.symbol}`}>
          {formatted}
        </div>
      </div>

      <div style={{ display: 'flex', gap: '8px', marginTop: '4px' }}>
        <button
          type="button"
          className="copy-button"
          onClick={handleCopy}
          title={`${formatted} ${unit.symbol} をコピー`}
          style={{ flex: 1 }}
        >
          {copied ? (
            <span className="copy-badge">
              <Check size={14} />
              コピー済
            </span>
          ) : (
            <>
              <Copy size={14} />
              <span>コピー</span>
            </>
          )}
        </button>

        <button
          type="button"
          className="base-select-button"
          onClick={handleSelectAsBase}
          disabled={isBase}
          title={isBase ? '現在選択中の基準単位です' : `${unit.name}を入力基準にする`}
          style={{ flex: 1.2 }}
        >
          {isBase ? (
            <span>基準単位</span>
          ) : (
            <>
              <ArrowRightLeft size={13} />
              <span>基準にする</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
}

import { useState, useMemo, ChangeEvent } from 'react';
import { Ruler, Calculator, X, CheckCircle2 } from 'lucide-react';
import { UnitKey } from './types';
import {
  UNITS,
  UNIT_KEYS,
  PRESETS,
  convertValue,
  getFormulaExplanation
} from './utils/converter';
import ConversionCard from './components/ConversionCard';

export default function App() {
  const [inputValue, setInputValue] = useState<string>('1');
  const [baseUnit, setBaseUnit] = useState<UnitKey>('m');
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const numericValue = useMemo(() => {
    if (!inputValue.trim()) return 0;
    const parsed = parseFloat(inputValue);
    return isNaN(parsed) ? 0 : parsed;
  }, [inputValue]);

  const results = useMemo(() => {
    return convertValue(numericValue, baseUnit);
  }, [numericValue, baseUnit]);

  const formulaExplanation = useMemo(() => {
    return getFormulaExplanation(baseUnit, numericValue);
  }, [baseUnit, numericValue]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '' || /^-?\d*\.?\d*$/.test(val)) {
      setInputValue(val);
    }
  };

  const handleClear = () => {
    setInputValue('');
  };

  const handleUnitSelect = (e: ChangeEvent<HTMLSelectElement>) => {
    setBaseUnit(e.target.value as UnitKey);
  };

  const handleApplyPreset = (value: number, unit: UnitKey) => {
    setInputValue(value.toString());
    setBaseUnit(unit);
  };

  const handleSelectAsBase = (key: UnitKey) => {
    setBaseUnit(key);
  };

  const handleCopy = (text: string, label: string) => {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => {
        setToastMessage(`${label} をコピーしました: ${text}`);
        setTimeout(() => setToastMessage(null), 2400);
      }).catch(() => {
        fallbackCopy(text, label);
      });
    } else {
      fallbackCopy(text, label);
    }
  };

  const fallbackCopy = (text: string, label: string) => {
    try {
      const textarea = document.createElement('textarea');
      textarea.value = text;
      textarea.style.position = 'fixed';
      textarea.style.opacity = '0';
      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setToastMessage(`${label} をコピーしました: ${text}`);
      setTimeout(() => setToastMessage(null), 2400);
    } catch {
      setToastMessage('コピーに失敗しました');
      setTimeout(() => setToastMessage(null), 2400);
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">
          <Ruler size={30} color="#2563eb" />
          <span>長さ単位一括変換ツール</span>
        </h1>
        <p className="subtitle">
          mm・cm・m・km・インチ・フィートをリアルタイム相互換算。入力値を全単位へ瞬時に展開します。
        </p>
      </header>

      <main className="main-layout">
        <section className="input-panel">
          <div className="input-group">
            <input
              type="text"
              inputMode="decimal"
              className="value-input"
              value={inputValue}
              onChange={handleInputChange}
              placeholder="数値を入力..."
              aria-label="変換する数値"
            />
            {inputValue && (
              <button
                type="button"
                className="clear-button"
                onClick={handleClear}
                title="入力をクリア"
                aria-label="入力をクリア"
              >
                <X size={15} />
              </button>
            )}
            <select
              className="unit-select"
              value={baseUnit}
              onChange={handleUnitSelect}
              aria-label="変換元の基準単位を選択"
            >
              {UNIT_KEYS.map((key) => {
                const def = UNITS[key];
                return (
                  <option key={key} value={key}>
                    {def.symbol} ({def.name})
                  </option>
                );
              })}
            </select>
          </div>

          <div className="preset-chips">
            {PRESETS.map((preset) => (
              <button
                key={preset.label}
                type="button"
                className="chip-button"
                onClick={() => handleApplyPreset(preset.value, preset.unit)}
              >
                {preset.label}
              </button>
            ))}
          </div>
        </section>

        <section className="results-section">
          <div className="results-grid">
            {results.map((result) => (
              <ConversionCard
                key={result.unit.key}
                result={result}
                isBase={result.unit.key === baseUnit}
                onSelectAsBase={handleSelectAsBase}
                onCopy={handleCopy}
              />
            ))}
          </div>
        </section>

        <section className="formula-section">
          <h2 className="formula-title">
            <Calculator size={18} color="#2563eb" />
            <span>換算の計算式と基準比率</span>
          </h2>
          <div className="formula-box">
            <p className="formula-content">{formulaExplanation}</p>
          </div>
        </section>
      </main>

      {toastMessage && (
        <div className="toast" role="status" aria-live="polite">
          <CheckCircle2 size={18} color="#4ade80" />
          <span>{toastMessage}</span>
        </div>
      )}
    </div>
  );
}
